function solve(input) {
  let s = input.trim();
  let neg = false;
  if (s[0] === '+' || s[0] === '-') {
    neg = s[0] === '-';
    s = s.slice(1);
  }
  let [intPart, fracPart = ''] = s.split('.');
  intPart = intPart.replace(/^0+(?=\d)/, '');
  fracPart = fracPart.replace(/0+$/, '');
  if (fracPart.length === 0) fracPart = '';
  // pad
  let f = fracPart;
  while (f.length < 3) f += '0';
  let keep = f.slice(0, 2);
  let rest = f.slice(2);
  // decide rounding
  let roundUp = false;
  if (rest.length > 0) {
    const first = rest[0];
    if (first > '5') roundUp = true;
    else if (first < '5') roundUp = false;
    else {
      // exactly 5: check remainder nonzero
      let remNonZero = rest.slice(1).split('').some(c => c !== '0');
      if (remNonZero) roundUp = true;
      else roundUp = (keep[1] - '0') % 2 === 1;
    }
  }
  let num = BigInt(intPart || '0') * 100n + BigInt(keep);
  if (roundUp) num += 1n;
  if (neg && num !== 0n) num = -num;
  const sign = num < 0n ? '-' : '';
  const abs = num < 0n ? -num : num;
  const whole = abs / 100n;
  const cents = (abs % 100n).toString().padStart(2, '0');
  return sign + whole.toString() + '.' + cents;
}

